    var notes=(noteSnippet(r.memo,100000)?'<div class="detail-note"><b>'+memoName+'</b><br />'+esc(r.memo)+'</div>':'')+(page==='purchasing'&&noteSnippet(r.comments,100000)?'<div class="detail-note"><b>Internal comments</b><br />'+esc(r.comments)+'</div>':'');
