  function render(){if(!data){byId('page').innerHTML='<div class="empty">No report snapshot is available.</div>';return}var s=sections.filter(function(x){return x.id===page})[0];byId('page-title').innerText=s.name;byId('page-subtitle').innerText=s.sub;var content=detailId&&page!=='scheduling'?detail():({overview:overview,ceo:ceo,kpis:kpis,sales:sales,quotes:quotes,enquiries:enquiries,production:production,scheduling:scheduling,dispatch:dispatch,purchasing:purchasing,maintenance:maintenance,database:database,settings:settings})[page]();byId('page').innerHTML=content;var cnt=byId('visible-count');if(cnt){var tbody=byId('page').getElementsByTagName('tbody')[0];cnt.innerText=(tbody?tbody.getElementsByTagName('tr').length:0)+' shown'}if(page==='production'&&!detailId)fillDraft()}
